fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());
    for &c in s.iter() {
        if c >= 'A' && c <= 'Z' {
            // ASCII uppercase range; safe to cast to u8
            let lower = (c as u8 + 32) as char;
            result.push(lower);
        } else {
            result.push(c);
        }
    }
    result
}